'use strict';
const manifestoVersion = '2026-11-11.1';
function manifestoTextHTML() {
  return '<article class="manifesto-text"><h1>Un outil prend vie quand on le partage</h1>\n<p class="manifesto-subtitle">Le manifeste des participants à CompagnieCraft</p>\n<p>J’ai créé cet outil pour faciliter la vie des troupes et donner plus de place à la création et à la rencontre. J’en ai posé les premières bases. À vous maintenant de vous l’approprier, de l’enrichir et de le partager.</p>\n<p>La suite s’écrit avec celles et ceux qui s’en servent.</p>\n<h2>Prendre part au projet</h2>\n<p>Participer, c’est faire vivre l’atelier : l’utiliser dans sa pratique, poser une question, signaler une difficulté, proposer une idée ou aider quelqu’un à trouver ses repères. Chacun arrive avec son expérience, ses envies et le temps dont il dispose.</p>\n<h2>Enrichir ce qui nous aide</h2>\n<p>Une adresse vérifiée, un retour de terrain, une méthode de répétition, une ressource, une correction ou du code : toutes ces contributions peuvent être utiles. Nous prenons soin de ce que nous ajoutons, indiquons nos sources et signalons ce qui reste à vérifier.</p>\n<h2>Faire circuler les savoir-faire</h2>\n<p>Ce que nous apprenons peut servir à d’autres. Nous partageons nos découvertes et nos expériences pour permettre à chacun d’avancer. Nous reconnaissons le travail des personnes qui nous ont aidés et citons les auteurs des ressources que nous transmettons.</p>\n<h2>Respecter les personnes et leurs choix</h2>\n<p>Nous accueillons les pratiques, les parcours et les niveaux d’expérience différents. Nous pouvons discuter une idée avec franchise tout en respectant la personne qui la porte. Nous demandons l’accord des personnes concernées avant de diffuser leurs coordonnées, leurs images, leurs documents ou leurs créations. Chacun choisit ce qu’il partage.</p>\n<h2>Prendre soin de la suite</h2>\n<p>Nous tenons à un code gratuit à installer soi-même et à des outils accessibles. Nous cherchons à les rendre plus simples, plus utiles et plus faciles à reprendre. Nous documentons ce que nous améliorons pour que d’autres puissent comprendre, poursuivre et transmettre à leur tour.</p>\n<p>Le projet grandit grâce à des contributions de toutes tailles. Chacun participe selon ses moyens ; la confiance se construit dans l’attention que nous portons au travail et aux personnes.</p>\n<p><strong>Les outils nous aident à préparer la scène. Le trésor, c’est l’échange humain.</strong></p></article>';
}
function manifestoFieldsHTML() {
  return '<div class="manifesto-signature"><h2>Mon engagement</h2><p>Je rejoins CompagnieCraft comme participant ou participante au projet. Je m’engage à faire vivre cet esprit dans mon usage de l’outil et dans mes échanges, selon mes possibilités.</p><label>Mon prénom et mon nom<input name="manifestoName" required maxlength="120" autocomplete="name"></label><label class="manifesto-check"><input type="checkbox" name="manifestoAccepted" required><span>J’ai lu le manifeste et j’adhère à son esprit. En validant, je le signe en mon nom.</span></label><p class="muted">Votre signature reste privée. Votre nom, la version du texte et la date de signature sont conservés avec votre compte.</p></div>';
}
function manifestoGateHTML() {
  return (
    '<section class="manifesto-sheet">' +
    manifestoTextHTML() +
    '<form id="manifesto-sign">' +
    manifestoFieldsHTML() +
    '<p role="alert" id="manifesto-error"></p><button class="primary" type="submit">Signer et rejoindre l’atelier</button><button type="button" class="secondary" data-manifesto-logout>Me déconnecter</button></form></section>'
  );
}
